import * as charset from './charset.ts';
import type { Pattern, Instruction, Captures, SearchResult } from './types.ts';

export class TooManySteps extends Error {}

export class BacktrackVM {
  program: Instruction[];
  groups: number;
  flags: string;
  text: string;
  steps: number;
  full: boolean;
  constructor(pattern: Pattern, text: string) {
    this.program = pattern.program;
    this.groups = pattern.groups;
    this.flags = pattern.flags;
    this.text = text;
    this.steps = 0;
    this.full = false;
  }

  execute(startInstruction: number, startPosition: number, captures: Captures, partial: boolean): SearchResult | null {
    const stack: {p: number; q: number; captures: Captures; visited: Set<number>}[] =
      [{p: startInstruction, q: startPosition, captures: captures.slice(), visited: new Set<number>()}];
    while (stack.length > 0) {
      let {p, q, captures: current, visited} = stack.pop()!;
      let failed = false;
      while (!failed) {
        this.steps++;
        if (this.steps > 200000) throw new TooManySteps();
        const instruction = this.program[p];
        switch (instruction.op) {
          case 'CHAR': case 'ANY': case 'CLASS':
            if (!charset.consumes(instruction, this.text, q, this.flags)) { failed = true; break; }
            q++;
            p++;
            visited = new Set<number>();
            break;
          case 'SPLIT':
            if (visited.has(p)) { failed = true; break; }
            visited.add(p);
            stack.push({p: instruction.y!, q, captures: current.slice(), visited: new Set(visited)});
            p = instruction.x!;
            break;
          case 'JMP': p = instruction.x!; break;
          case 'SAVE': current[instruction.group!] = q; p++; break;
          case 'ASSERT':
            if (charset.assertion(instruction.assertion!, this.text, q, this.flags)) p++;
            else failed = true;
            break;
          case 'BACKREF': {
            const first = current[2 * instruction.group!];
            const last = current[2 * instruction.group! + 1];
            if (first === null || last === null || first > last || q + last - first > this.text.length) {
              failed = true;
              break;
            }
            const length = last - first;
            for (let index = 0; index < length; index++) {
              if (!charset.same(this.text.charCodeAt(q + index), this.text.charCodeAt(first + index), this.flags)) {
                failed = true;
                break;
              }
            }
            if (!failed) {
              q += length;
              p++;
              if (length > 0) visited = new Set<number>();
            }
            break;
          }
          case 'LOOK': {
            const result = this.execute(p + 1, q, current, true);
            if (instruction.kind === 'NOT') {
              if (result === null) p = instruction.x!;
              else failed = true;
            } else if (result === null) failed = true;
            else {
              current = result.captures;
              if (instruction.kind === 'ATOMIC') {
                if (result.position > q) visited = new Set<number>();
                q = result.position;
              }
              p = instruction.x!;
            }
            break;
          }
          case 'MATCH':
            if (partial || !this.full || q === this.text.length) return {captures: current, position: q};
            failed = true;
            break;
        }
      }
    }
    return null;
  }

  search(start: number, full: boolean): Captures | null {
    this.full = full;
    const first = full ? 0 : start;
    const last = full ? 0 : this.text.length;
    for (let position = first; position <= last; position++) {
      const captures = Array(2 * this.groups + 2).fill(null);
      const result = this.execute(0, position, captures, false);
      if (result !== null) return result.captures;
    }
    return null;
  }
}

export function digit(code: number): boolean { return code >= 48 && code <= 57; }
export function letter(code: number): boolean { return (code >= 65 && code <= 90) || (code >= 97 && code <= 122); }
export function word(code: number): boolean { return letter(code) || digit(code) || code === 95; }
export function swapCase(code: number): number { return code >= 65 && code <= 90 ? code + 32 : code - 32; }

export const digits = new Set<number>();
export const words = new Set<number>();
export const spaces = new Set<number>([9, 10, 11, 12, 13, 32]);
for (let code = 0; code < 128; code++) {
  if (digit(code)) digits.add(code);
  if (word(code)) words.add(code);
}

export function complement(set: Set<number>): Set<number> {
  const result = new Set<number>();
  for (let code = 0; code < 128; code++) if (!set.has(code)) result.add(code);
  return result;
}

export function shorthand(character: string): {set: Set<number>; negated: boolean} {
  const lower = character === 'd' || character === 'D' ? 'd' : character === 'w' || character === 'W' ? 'w' : 's';
  const set = lower === 'd' ? digits : lower === 'w' ? words : spaces;
  return {set, negated: character !== lower};
}

export function same(first: number, second: number, flags: string): boolean {
  return first === second || (flags.includes('i') && letter(first) && swapCase(first) === second);
}

export function classMatches(set: Set<number>, negated: boolean, code: number, flags: string): boolean {
  const present = set.has(code) || (flags.includes('i') && letter(code) && set.has(swapCase(code)));
  return present !== negated;
}

export function consumes(instruction: import('./types.ts').Instruction, text: string, position: number, flags: string): boolean {
  if (position >= text.length) return false;
  const code = text.charCodeAt(position);
  if (instruction.op === 'CHAR') return same(code, instruction.character!, flags);
  if (instruction.op === 'ANY') return flags.includes('s') || code !== 10;
  return classMatches(instruction.set!, instruction.negated!, code, flags);
}

export function assertion(kind: string, text: string, position: number, flags: string): boolean {
  if (kind === 'BOL') return position === 0 || (flags.includes('m') && text[position - 1] === '\n');
  if (kind === 'EOL') return position === text.length || (flags.includes('m') && text[position] === '\n');
  const before = position > 0 && word(text.charCodeAt(position - 1));
  const after = position < text.length && word(text.charCodeAt(position));
  return kind === 'WORD' ? before !== after : before === after;
}

import type { Instruction } from './types.ts';

export function character(code: number): string {
  if (code >= 33 && code <= 126 && ![92, 93, 94, 45].includes(code)) return String.fromCharCode(code);
  return '\\x' + code.toString(16).toUpperCase().padStart(2, '0');
}

export function setNotation(set: Set<number>, negated = false): string {
  const parts = [];
  for (let start = 0; start < 128; start++) {
    if (!set.has(start)) continue;
    let end = start;
    while (end + 1 < 128 && set.has(end + 1)) end++;
    if (end === start) parts.push(character(start));
    else if (end === start + 1) parts.push(character(start), character(end));
    else parts.push(character(start) + '-' + character(end));
    start = end;
  }
  return '[' + (negated ? '^' : '') + parts.join('') + ']';
}

export function instruction(value: Instruction): string {
  if (value.op === 'CHAR') return 'CHAR ' + character(value.character!);
  if (value.op === 'CLASS') return 'CLASS ' + setNotation(value.set!, value.negated!);
  if (value.op === 'SPLIT') return `SPLIT ${value.x}, ${value.y}`;
  if (value.op === 'JMP') return 'JMP ' + value.x;
  if (value.op === 'SAVE' || value.op === 'BACKREF') return value.op + ' ' + value.group;
  if (value.op === 'ASSERT') return 'ASSERT ' + value.assertion;
  if (value.op === 'LOOK') return `LOOK ${value.kind} ${value.x}`;
  return value.op;
}

export function quote(value: string): string {
  let result = '"';
  for (const character_ of value) {
    if (character_ === '\\') result += '\\\\';
    else if (character_ === '"') result += '\\"';
    else if (character_ === '\n') result += '\\n';
    else if (character_ === '\t') result += '\\t';
    else result += character_;
  }
  return result + '"';
}

import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import * as charset from './charset.ts';
import * as formatter from './formatter.ts';
import {BacktrackVM, TooManySteps} from './backtrack_vm.ts';
import {PikeVM} from './pike_vm.ts';
import type {
  Captures, Pattern, RegexNode, BackReferenceNode, RegexProperties, Instruction,
  RegexCommand, EngineResult, RegexVM, SearchResult, RepetitionNode,
} from './types.ts';

class PatternError extends Error {
  column: number;
  constructor(message: string, column: number) { super(message); this.column = column; }
}

function quantifier(character: string): boolean {
  return character === '*' || character === '+' || character === '?' || character === '{';
}

class PatternParser {
  source: string;
  index: number;
  groups: number;
  names: Map<string, number>;
  references: BackReferenceNode[];
  constructor(source: string) {
    this.source = source;
    this.index = 0;
    this.groups = 0;
    this.names = new Map<string, number>();
    this.references = [];
  }

  peek(): string { return this.source[this.index]; }
  fail(message: string, column = this.index + 1): never { throw new PatternError(message, column); }
  take(character: string): boolean {
    if (this.peek() !== character) return false;
    this.index++;
    return true;
  }

  parse(): RegexNode {
    const root = this.alternation();
    if (this.index < this.source.length) this.fail('unmatched )');
    for (const reference of this.references) {
      if (reference.name !== undefined) {
        if (!this.names.has(reference.name)) this.fail('unknown group name', reference.column);
        reference.group = this.names.get(reference.name)!;
      } else if (reference.group! > this.groups) this.fail('invalid group reference', reference.column);
    }
    return root;
  }

  alternation(): RegexNode {
    const alternatives = [this.concatenation()];
    while (this.take('|')) alternatives.push(this.concatenation());
    return alternatives.length === 1 ? alternatives[0] : {kind: 'alternation', elements: alternatives};
  }

  concatenation(): RegexNode {
    const elements: RegexNode[] = [];
    while (this.index < this.source.length && this.peek() !== '|' && this.peek() !== ')') elements.push(this.quantified());
    return elements.length === 1 ? elements[0] : {kind: 'concatenation', elements};
  }

  quantified(): RegexNode {
    if (quantifier(this.peek())) this.fail('nothing to repeat');
    const content = this.element();
    if (!quantifier(this.peek())) return content;
    if (content.kind === 'assertion' || content.kind === 'lookahead') this.fail('nothing to repeat');
    let minimum: number;
    let maximum: number | null;
    if (this.take('*')) { minimum = 0; maximum = null; }
    else if (this.take('+')) { minimum = 1; maximum = null; }
    else if (this.take('?')) { minimum = 0; maximum = 1; }
    else ({minimum, maximum} = this.bounds());
    const mode: RepetitionNode['mode'] = this.take('?') ? 'lazy' : this.take('+') ? 'possessive' : 'greedy';
    if (quantifier(this.peek())) this.fail('nested quantifier');
    return {kind: 'repetition', content, minimum, maximum, mode};
  }

  bounds(): {minimum: number; maximum: number | null} {
    const column = ++this.index;
    const number = () => {
      const start = this.index;
      while (charset.digit(this.source.charCodeAt(this.index))) this.index++;
      if (this.index === start) this.fail('invalid quantifier', column);
      return Number(this.source.slice(start, this.index));
    };
    const minimum = number();
    let maximum = minimum;
    if (this.take(',')) maximum = this.peek() === '}' ? null : number();
    if (!this.take('}')) this.fail('invalid quantifier', column);
    if (minimum > 100 || (maximum !== null && maximum > 100)) this.fail('quantifier too large', column);
    if (maximum !== null && minimum > maximum) this.fail('quantifier range out of order', column);
    return {minimum, maximum};
  }

  element(): RegexNode {
    if (this.peek() === '(') return this.group();
    if (this.peek() === '[') return this.characterClass();
    if (this.peek() === '\\') return this.escape();
    const character = this.source[this.index++];
    if (character === '.') return {kind: 'any'};
    if (character === '^' || character === '$') return {kind: 'assertion', assertion: character === '^' ? 'BOL' : 'EOL'};
    return {kind: 'literal', character: character.charCodeAt(0)};
  }

  name(): {name: string; column: number} {
    const start = this.index;
    if (charset.letter(this.source.charCodeAt(this.index)) || this.peek() === '_') {
      this.index++;
      while (charset.word(this.source.charCodeAt(this.index))) this.index++;
    }
    if (this.index === start || this.peek() !== '>') this.fail('invalid group name');
    const name = this.source.slice(start, this.index);
    this.index++;
    return {name, column: start + 1};
  }

  group(): RegexNode {
    const column = ++this.index;
    let kind = 'capture';
    let name: {name: string; column: number} | null = null;
    if (this.take('?')) {
      const character = this.peek();
      if (character === ':') kind = 'noncapture';
      else if (character === '=') kind = 'positive';
      else if (character === '!') kind = 'negative';
      else if (character === '<') kind = 'named';
      else this.fail('invalid group', column);
      this.index++;
    }
    if (kind === 'named') {
      name = this.name();
      if (this.names.has(name.name)) this.fail('duplicate group name', name.column);
    }
    let group: number | null = null;
    if (kind === 'capture' || kind === 'named') {
      group = ++this.groups;
      if (name !== null) this.names.set(name.name, group);
    }
    const content = this.alternation();
    if (!this.take(')')) this.fail('missing )', column);
    if (kind === 'noncapture') return content;
    if (kind === 'positive' || kind === 'negative') return {kind: 'lookahead', positive: kind === 'positive', content};
    return {kind: 'group', group: group!, content};
  }

  classItem(): {character?: number; set?: Set<number>} {
    const column = this.index + 1;
    const character = this.source[this.index++];
    if (character !== '\\') return {character: character.charCodeAt(0)};
    if (this.index === this.source.length) this.fail('trailing backslash', column);
    const escaped = this.source[this.index++];
    if ('dDwWsS'.includes(escaped)) {
      const {set, negated} = charset.shorthand(escaped);
      return {set: negated ? charset.complement(set) : set};
    }
    if (escaped === 'n' || escaped === 't') return {character: escaped === 'n' ? 10 : 9};
    if (charset.letter(escaped.charCodeAt(0)) || charset.digit(escaped.charCodeAt(0))) this.fail('invalid escape', column);
    return {character: escaped.charCodeAt(0)};
  }

  characterClass(): RegexNode {
    const column = ++this.index;
    const negated = this.take('^');
    if (this.peek() === ']') this.fail('empty class');
    const set = new Set<number>();
    for (;;) {
      if (this.index === this.source.length) this.fail('missing ]', column);
      if (this.take(']')) break;
      const first = this.classItem();
      if (this.peek() === '-' && this.index + 1 < this.source.length && this.source[this.index + 1] !== ']') {
        const dash = ++this.index;
        if (first.set !== undefined) this.fail('invalid range', dash);
        const last = this.classItem();
        if (last.set !== undefined || first.character! > last.character!) this.fail('invalid range', dash);
        for (let code = first.character!; code <= last.character!; code++) set.add(code);
      } else if (first.set !== undefined) {
        for (const code of first.set) set.add(code);
      } else set.add(first.character!);
    }
    return {kind: 'class', set, negated};
  }

  escape(): RegexNode {
    const column = ++this.index;
    if (this.index === this.source.length) this.fail('trailing backslash', column);
    const character = this.source[this.index++];
    if ('dDwWsS'.includes(character)) return {kind: 'class', ...charset.shorthand(character)};
    if (character === 'b' || character === 'B') return {kind: 'assertion', assertion: character === 'b' ? 'WORD' : 'NOTWORD'};
    if (character === 'n' || character === 't') return {kind: 'literal', character: character === 'n' ? 10 : 9};
    let reference: BackReferenceNode;
    if (character >= '1' && character <= '9') {
      const start = this.index - 1;
      while (charset.digit(this.source.charCodeAt(this.index))) this.index++;
      reference = {kind: 'backreference', group: Number(this.source.slice(start, this.index)), column};
    } else if (character === 'k') {
      if (!this.take('<')) this.fail('invalid escape', column);
      reference = {kind: 'backreference', name: this.name().name, column};
    } else {
      const code = character.charCodeAt(0);
      if (charset.letter(code) || charset.digit(code)) this.fail('invalid escape', column);
      return {kind: 'literal', character: code};
    }
    this.references.push(reference);
    return reference;
  }
}

function compile(root: RegexNode): Instruction[] {
  const program: Instruction[] = [];
  const emit = (op: Instruction['op'], fields: Partial<Instruction> = {}): number => { program.push({op, ...fields}); return program.length - 1; };
  function split(index: number, repeat: number, stop: number, mode: string): void {
    program[index].x = mode === 'lazy' ? stop : repeat;
    program[index].y = mode === 'lazy' ? repeat : stop;
  }
  function repeat(node: RepetitionNode): void {
    const {content, minimum, maximum, mode} = node;
    if (mode === 'possessive') {
      const look = emit('LOOK', {kind: 'ATOMIC'});
      repeat({...node, mode: 'greedy'});
      emit('MATCH');
      program[look].x = program.length;
    } else if (maximum === null && minimum === 0) {
      const head = emit('SPLIT');
      visit(content);
      emit('JMP', {x: head});
      split(head, head + 1, program.length, mode);
    } else if (maximum === null) {
      for (let index = 0; index < minimum - 1; index++) visit(content);
      const head = program.length;
      visit(content);
      const branch = emit('SPLIT');
      split(branch, head, program.length, mode);
    } else {
      for (let index = 0; index < minimum; index++) visit(content);
      const branches: number[] = [];
      for (let index = minimum; index < maximum; index++) {
        const branch = emit('SPLIT');
        branches.push(branch);
        visit(content);
      }
      for (const branch of branches) split(branch, branch + 1, program.length, mode);
    }
  }
  function visit(node: RegexNode): void {
    switch (node.kind) {
      case 'literal': emit('CHAR', {character: node.character}); break;
      case 'any': emit('ANY'); break;
      case 'class': emit('CLASS', {set: node.set, negated: node.negated}); break;
      case 'assertion': emit('ASSERT', {assertion: node.assertion}); break;
      case 'backreference': emit('BACKREF', {group: node.group!}); break;
      case 'group': emit('SAVE', {group: 2 * node.group}); visit(node.content); emit('SAVE', {group: 2 * node.group + 1}); break;
      case 'lookahead': {
        const look = emit('LOOK', {kind: node.positive ? 'AHEAD' : 'NOT'});
        visit(node.content);
        emit('MATCH');
        program[look].x = program.length;
        break;
      }
      case 'concatenation': for (const element of node.elements) visit(element); break;
      case 'alternation': {
        const jumps: number[] = [];
        for (let index = 0; index + 1 < node.elements.length; index++) {
          const branch = emit('SPLIT');
          program[branch].x = program.length;
          visit(node.elements[index]);
          jumps.push(emit('JMP'));
          program[branch].y = program.length;
        }
        visit(node.elements[node.elements.length - 1]);
        for (const jump of jumps) program[jump].x = program.length;
        break;
      }
      case 'repetition': repeat(node); break;
    }
  }
  emit('SAVE', {group: 0});
  visit(root);
  emit('SAVE', {group: 1});
  emit('MATCH');
  return program;
}

function properties(node: RegexNode, flags: string): RegexProperties {
  if (node.kind === 'assertion' || node.kind === 'lookahead') return {minimum: 0, maximum: 0, first: new Set(), nullable: true};
  if (node.kind === 'group') return properties(node.content, flags);
  if (node.kind === 'literal' || node.kind === 'any' || node.kind === 'class' || node.kind === 'backreference') {
    const first = new Set<number>();
    for (let code = 0; code < 128; code++) {
      let present;
      if (node.kind === 'literal') present = charset.same(code, node.character, flags);
      else if (node.kind === 'any') present = flags.includes('s') || code !== 10;
      else if (node.kind === 'class') present = charset.classMatches(node.set, node.negated, code, flags);
      else present = true;
      if (present) first.add(code);
    }
    const reference = node.kind === 'backreference';
    return {minimum: reference ? 0 : 1, maximum: reference ? null : 1, first, nullable: reference};
  }
  if (node.kind === 'repetition') {
    const content = properties(node.content, flags);
    const maximum = content.maximum === 0 ? 0 : content.maximum === null || node.maximum === null ? null : node.maximum * content.maximum;
    return {minimum: node.minimum * content.minimum, maximum,
      first: node.maximum === 0 ? new Set() : content.first,
      nullable: node.maximum === 0 || node.minimum === 0 || content.nullable};
  }
  const elements = node.elements.map(element => properties(element, flags));
  const first = new Set();
  if (node.kind === 'concatenation') {
    let minimum = 0;
    let maximum = 0;
    let nullable = true;
    for (const element of elements) {
      minimum += element.minimum;
      maximum = maximum === null || element.maximum === null ? null : maximum + element.maximum;
      if (nullable) {
        for (const code of element.first) first.add(code);
        nullable = element.nullable;
      }
    }
    return {minimum, maximum, first, nullable};
  }
  let minimum = elements[0].minimum;
  let maximum = elements[0].maximum;
  let nullable = false;
  for (const element of elements) {
    minimum = Math.min(minimum, element.minimum);
    maximum = maximum === null || element.maximum === null ? null : Math.max(maximum, element.maximum);
    nullable ||= element.nullable;
    for (const code of element.first) first.add(code);
  }
  return {minimum, maximum, first, nullable};
}

function readLines(file: string): string[] { return readFileSync('input/' + file, 'ascii').split('\n').slice(0, -1); }

function decodeQuoted(source: string): string {
  let result = '';
  const escapes: Record<string, string> = {n: '\n', t: '\t', '\\': '\\', '"': '"'};
  for (let index = 1; index + 1 < source.length; index++) {
    if (source[index] === '\\') result += escapes[source[++index]];
    else result += source[index];
  }
  return result;
}

function readPatterns(): Map<string, Pattern> {
  const patterns = new Map<string, Pattern>();
  for (const line of readLines('patterns.txt')) {
    const first = line.indexOf(' ');
    const second = line.indexOf(' ', first + 1);
    const pattern: Pattern = {name: line.slice(0, first), flags: line.slice(first + 1, second),
      source: line.slice(second + 1), error: null, groups: 0, names: new Map<string, number>(),
      program: [], properties: {minimum: 0, maximum: 0, first: new Set<number>(), nullable: true},
      pike: false};
    const parser = new PatternParser(pattern.source);
    try {
      const root = parser.parse();
      pattern.groups = parser.groups;
      pattern.names = parser.names;
      pattern.program = compile(root);
      pattern.properties = properties(root, pattern.flags);
      pattern.pike = pattern.program.every(instruction => instruction.op !== 'BACKREF' && instruction.op !== 'LOOK');
    } catch (error) {
      if (!(error instanceof PatternError)) throw error;
      pattern.error = {message: error.message, column: error.column};
    }
    patterns.set(pattern.name, pattern);
  }
  return patterns;
}

function templateParts(template: string, pattern: Pattern): (string | number)[] | null {
  const parts: (string | number)[] = [];
  let literal = '';
  let index = 0;
  while (index < template.length) {
    if (template[index] !== '$') { literal += template[index++]; continue; }
    if (template[index + 1] === '$') { literal += '$'; index += 2; continue; }
    if (literal !== '') { parts.push(literal); literal = ''; }
    let group;
    if (charset.digit(template.charCodeAt(index + 1))) {
      group = Number(template[index + 1]);
      index += 2;
    } else if (template[index + 1] === '{') {
      const end = template.indexOf('}', index + 2);
      if (end === -1) return null;
      const name = template.slice(index + 2, end);
      let numeric = name.length > 0;
      for (let at = 0; at < name.length; at++) if (!charset.digit(name.charCodeAt(at))) numeric = false;
      if (numeric) group = Number(name);
      else if (pattern.names.has(name)) group = pattern.names.get(name)!;
      else return null;
      index = end + 1;
    } else return null;
    if (group > pattern.groups) return null;
    parts.push(group);
  }
  if (literal !== '') parts.push(literal);
  return parts;
}

function setGroup(captures: Captures, group: number): boolean { return captures[2 * group] !== null && captures[2 * group + 1] !== null; }
function captured(text: string, captures: Captures, group: number): string { return text.slice(captures[2 * group]!, captures[2 * group + 1]!); }

function expand(parts: (string | number)[], text: string, captures: Captures): string {
  return parts.map(part => typeof part === 'string' ? part : setGroup(captures, part) ? captured(text, captures, part) : '').join('');
}

function sequence(vm: RegexVM, command: RegexCommand, text: string): Captures[] {
  if (command.kind === 'MATCH' || command.kind === 'SEARCH' || (command.kind === 'REPLACE' && command.mode === 'FIRST')) {
    const match = vm.search(0, command.kind === 'MATCH');
    return match === null ? [] : [match];
  }
  const matches: Captures[] = [];
  let start = 0;
  while (start <= text.length) {
    const match = vm.search(start, false);
    if (match === null) break;
    matches.push(match);
    start = match[1] > match[0] ? match[1] : match[1] + 1;
  }
  return matches;
}

function runEngines(pattern: Pattern, text: string, command: RegexCommand): EngineResult {
  const backtrack = new BacktrackVM(pattern, text);
  let first: Captures[] | null = null;
  let aborted = false;
  try { first = sequence(backtrack, command, text); }
  catch (error) {
    if (!(error instanceof TooManySteps)) throw error;
    aborted = true;
  }
  const steps: EngineResult['steps'] = [['backtrack', backtrack.steps]];
  if (!pattern.pike) return {steps, matches: first, label: 'backtrack', failure: aborted ? 'TOO_MANY_STEPS' : null};
  const pike = new PikeVM(pattern, text);
  const second = sequence(pike, command, text);
  steps.push(['pike', pike.steps]);
  if (aborted) return {steps, matches: second, label: 'pike (backtrack: TOO_MANY_STEPS)', failure: null};
  const equal = first!.length === second.length && first!.every((match, index) =>
    match.length === second[index].length && match.every((value, group) => value === second[index][group]));
  return {steps, matches: first!, label: 'both', failure: equal ? null : 'MISMATCH'};
}

function appendMatch(lines: string[], pattern: Pattern, text: string, captures: Captures): void {
  for (let group = 0; group <= pattern.groups; group++) {
    const label = group === 0 ? 'match' : 'group ' + group;
    const span = setGroup(captures, group) ? `${captures[2 * group]}-${captures[2 * group + 1]} ${formatter.quote(captured(text, captures, group))}` : '-';
    lines.push(label + ' ' + span);
  }
}

function appendResult(lines: string[], pattern: Pattern, text: string, command: RegexCommand, result: EngineResult): void {
  if (result.failure !== null) { lines.push(result.failure); return; }
  lines.push('engine ' + result.label);
  const matches = result.matches!;
  if (command.kind === 'MATCH' || command.kind === 'SEARCH') {
    if (matches.length === 0) lines.push('no match');
    else appendMatch(lines, pattern, text, matches[0]);
  } else if (command.kind === 'FINDALL') {
    lines.push('matches ' + matches.length);
    for (const match of matches) appendMatch(lines, pattern, text, match);
  } else if (command.kind === 'REPLACE') {
    const pieces = [];
    let previous = 0;
    for (const match of matches) {
      pieces.push(text.slice(previous, match[0]), expand(command.template!, text, match));
      previous = match[1];
    }
    pieces.push(text.slice(previous));
    lines.push('replacements ' + matches.length, 'result ' + formatter.quote(pieces.join('')));
  } else {
    lines.push('pieces ' + (matches.length + 1));
    lines.push('piece ' + formatter.quote(text.slice(0, matches.length === 0 ? text.length : matches[0][0])));
    for (let index = 0; index < matches.length; index++) {
      const match = matches[index];
      for (let group = 1; group <= pattern.groups; group++) {
        lines.push(`group ${group} ` + (setGroup(match, group) ? formatter.quote(captured(text, match, group)) : '-'));
      }
      const end = index + 1 < matches.length ? matches[index + 1][0] : text.length;
      lines.push('piece ' + formatter.quote(text.slice(match[1], end)));
    }
  }
}

function appendProgram(lines: string[], pattern: Pattern): void {
  const properties_ = pattern.properties;
  const names = [...pattern.names].map(([name, group]) => `${name}:${group}`).join(',') || '-';
  const first = properties_.first.size === 0 ? '-' : formatter.setNotation(properties_.first);
  const maximum = properties_.maximum === null ? 'inf' : properties_.maximum;
  lines.push('=== ' + pattern.name);
  lines.push(`flags=${pattern.flags} groups=${pattern.groups} names=${names} length=${properties_.minimum}..${maximum} ` +
    `first=${first} pike=${pattern.pike ? 'yes' : 'no'} size=${pattern.program.length}`);
  pattern.program.forEach((instruction, index) => lines.push(index + ' ' + formatter.instruction(instruction)));
}

function main(): void {
  const patterns = readPatterns();
  const subjects = new Map<string, string>(readLines('subjects.txt').map(line => {
    const space = line.indexOf(' ');
    return [line.slice(0, space), decodeQuoted(line.slice(space + 1))];
  }));
  const outputs: Record<'results.txt' | 'programs.txt' | 'steps.csv' | 'errors.txt', string[]> =
    {'results.txt': [], 'programs.txt': [], 'steps.csv': ['command,engine,steps'], 'errors.txt': []};
  for (const pattern of patterns.values()) {
    if (pattern.error === null) continue;
    outputs['errors.txt'].push(`${pattern.name}: ${pattern.error.message} at column ${pattern.error.column}`,
      '  ' + pattern.source, ' '.repeat(pattern.error.column + 1) + '^');
  }
  const commands = readLines('commands.txt');
  for (let index = 0; index < commands.length; index++) {
    const line = commands[index];
    const words = line.split(' ');
    const command: RegexCommand = {kind: words[0], mode: words[0] === 'REPLACE' ? words[1] : null, template: null};
    const pattern = patterns.get(words[command.kind === 'REPLACE' ? 2 : 1])!;
    outputs['results.txt'].push(`#${index + 1} ${line}`);
    if (pattern.error !== null) { outputs['results.txt'].push('invalid pattern'); continue; }
    if (command.kind === 'LIST') {
      outputs['results.txt'].push('instructions ' + pattern.program.length);
      appendProgram(outputs['programs.txt'], pattern);
      continue;
    }
    const text = subjects.get(words[command.kind === 'REPLACE' ? 3 : 2])!;
    if (command.kind === 'REPLACE') {
      let space = -1;
      for (let count = 0; count < 4; count++) space = line.indexOf(' ', space + 1);
      command.template = templateParts(decodeQuoted(line.slice(space + 1)), pattern);
      if (command.template === null) { outputs['results.txt'].push('invalid template'); continue; }
    }
    const result = runEngines(pattern, text, command);
    for (const [engine, steps] of result.steps) outputs['steps.csv'].push(`${index + 1},${engine},${steps}`);
    appendResult(outputs['results.txt'], pattern, text, command, result);
  }
  if (outputs['programs.txt'].length === 0) outputs['programs.txt'].push('no programs');
  if (outputs['errors.txt'].length === 0) outputs['errors.txt'].push('no errors');
  mkdirSync('output', {recursive: true});
  for (const [file, lines] of Object.entries(outputs)) writeFileSync('output/' + file, lines.join('\n') + '\n', 'ascii');
}

main();

import * as charset from './charset.ts';
import type { Pattern, Instruction, Captures } from './types.ts';

interface Thread {p: number; captures: Captures}
interface ThreadList {threads: Thread[]; marks: Set<number>}
function threadList(): ThreadList { return {threads: [], marks: new Set<number>()}; }

export class PikeVM {
  program: Instruction[];
  groups: number;
  flags: string;
  text: string;
  steps: number;
  constructor(pattern: Pattern, text: string) {
    this.program = pattern.program;
    this.groups = pattern.groups;
    this.flags = pattern.flags;
    this.text = text;
    this.steps = 0;
  }

  add(list: ThreadList, instructionNumber: number, captures: Captures, position: number): void {
    const pending: Thread[] = [{p: instructionNumber, captures: captures.slice()}];
    while (pending.length > 0) {
      const {p, captures: current} = pending.pop()!;
      if (list.marks.has(p)) continue;
      list.marks.add(p);
      this.steps++;
      const instruction = this.program[p];
      switch (instruction.op) {
        case 'JMP': pending.push({p: instruction.x!, captures: current}); break;
        case 'SPLIT':
          pending.push({p: instruction.y!, captures: current.slice()}, {p: instruction.x!, captures: current.slice()});
          break;
        case 'SAVE': {
          const changed = current.slice();
          changed[instruction.group!] = position;
          pending.push({p: p + 1, captures: changed});
          break;
        }
        case 'ASSERT':
          if (charset.assertion(instruction.assertion!, this.text, position, this.flags)) pending.push({p: p + 1, captures: current});
          break;
        default: list.threads.push({p, captures: current.slice()});
      }
    }
  }

  search(start: number, full: boolean): Captures | null {
    let match: Captures | null = null;
    let list = threadList();
    let position = start;
    for (;;) {
      if (match === null && (!full || position === start)) this.add(list, 0, Array(2 * this.groups + 2).fill(null), position);
      const next = threadList();
      for (const thread of list.threads) {
        this.steps++;
        const instruction = this.program[thread.p];
        if (instruction.op === 'MATCH') {
          if (!full || position === this.text.length) { match = thread.captures.slice(); break; }
        } else if (charset.consumes(instruction, this.text, position, this.flags)) {
          this.add(next, thread.p + 1, thread.captures, position + 1);
        }
      }
      if (position === this.text.length) break;
      if (next.threads.length === 0 && (match !== null || full)) break;
      list = next;
      position++;
    }
    return match;
  }
}

export type Captures = (number | null)[];
export type Engine = 'backtrack' | 'pike';

export interface Instruction {
  op: 'CHAR' | 'ANY' | 'CLASS' | 'SPLIT' | 'JMP' | 'SAVE' | 'ASSERT' | 'BACKREF' | 'LOOK' | 'MATCH';
  character?: number;
  set?: Set<number>;
  negated?: boolean;
  x?: number;
  y?: number;
  group?: number;
  assertion?: string;
  kind?: string;
}

export interface LiteralNode { kind: 'literal'; character: number }
export interface AnyNode { kind: 'any' }
export interface ClassNode { kind: 'class'; set: Set<number>; negated: boolean }
export interface AssertionNode { kind: 'assertion'; assertion: string }
export interface BackReferenceNode {
  kind: 'backreference';
  group?: number;
  name?: string;
  column: number;
}
export interface GroupNode { kind: 'group'; group: number; content: RegexNode }
export interface LookaheadNode { kind: 'lookahead'; positive: boolean; content: RegexNode }
export interface CompositeNode { kind: 'alternation' | 'concatenation'; elements: RegexNode[] }
export interface RepetitionNode {
  kind: 'repetition';
  content: RegexNode;
  minimum: number;
  maximum: number | null;
  mode: 'lazy' | 'greedy' | 'possessive';
}
export type RegexNode =
  | LiteralNode | AnyNode | ClassNode | AssertionNode | BackReferenceNode
  | GroupNode | LookaheadNode | CompositeNode | RepetitionNode;

export interface RegexProperties {
  minimum: number;
  maximum: number | null;
  first: Set<number>;
  nullable: boolean;
}

export interface Pattern {
  name: string;
  flags: string;
  source: string;
  error: {message: string; column: number} | null;
  groups: number;
  names: Map<string, number>;
  program: Instruction[];
  properties: RegexProperties;
  pike: boolean;
}

export interface SearchResult {
  captures: Captures;
  position: number;
}

export interface RegexCommand {
  kind: string;
  mode: string | null;
  template: (string | number)[] | null;
}

export interface EngineResult {
  steps: [Engine, number][];
  matches: Captures[] | null;
  label: string;
  failure: string | null;
}

export type RegexVM = { search(start: number, full: boolean): Captures | null };
